def _connect(ws):
    database = Path(ws).resolve().parent / "system" / "microsoft_planner_actions" / "state.db"
    connection = sqlite3.connect(f"file:{database}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    return connection


def _rows_hash(rows):
    payload = json.dumps(
        [dict(row) for row in rows],
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _parse_timestamp(value):
    if not value:
        return None
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def check_planner_card_corrected(ws):
    try:
        with _connect(ws) as connection:
            row = connection.execute(
                "SELECT work_status, completed_at, row_version FROM work_items WHERE work_item_id = ?",
                (TARGET_ID,),
            ).fetchone()
    except Exception as error:
        return {"score": 0, "detail": f"Could not read Planner card: {error}"}
    if row is None:
        return {"score": 0, "detail": "Target Planner card is missing"}
    actual = dict(row)
    expected = {
        "work_status": "AwaitingManagerDecision",
        "completed_at": None,
        "row_version": 5,
    }
    if actual == expected:
        return {"score": 1, "detail": "Target card has the corrected open status, cleared completion time, and version 5"}
    return {"score": 0, "detail": f"Target card post-state is incorrect: {actual}"}


def check_single_reconciliation_audit_added(ws):
    try:
        with _connect(ws) as connection:
            rows = connection.execute(
                "SELECT * FROM work_item_updates WHERE work_item_id = ? ORDER BY datetime(updated_at), update_id",
                (TARGET_ID,),
            ).fetchall()
    except Exception as error:
        return {"score": 0, "detail": f"Could not read target audit history: {error}"}
    if len(rows) != 3:
        return {"score": 0, "detail": f"Expected exactly three target audit rows after one append; found {len(rows)}"}
    new_rows = [dict(row) for row in rows if row["update_id"] not in ORIGINAL_UPDATE_IDS]
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one newly identified audit row; found {len(new_rows)}"}
    row = new_rows[0]
    structural_ok = (
        row["update_type"] in {"StatusChange", "Reconciliation"}
        and row["prior_status"] == "Completed"
        and row["new_status"] == "AwaitingManagerDecision"
        and _parse_timestamp(row["updated_at"]) > _parse_timestamp("2025-09-30T16:44:00+01:00")
    )
    note = " ".join((row["note_text"] or "").lower().replace("-", " ").split())
    note_ok = "manager" in note and any(
        marker in note
        for marker in ("reconcil", "supersed", "latest", "correct", "referral", "not completion", "16:44")
    )
    if structural_ok and note_ok:
        return {"score": 1, "detail": "Exactly one meaningful reconciliation audit row records the completed-to-manager-decision correction"}
    return {"score": 0, "detail": f"New audit row does not fully record the reconciliation: {row}"}


def check_existing_database_records_preserved(ws):
    try:
        with _connect(ws) as connection:
            checks = {
                "action_plans": connection.execute("SELECT * FROM action_plans ORDER BY plan_id").fetchall(),
                "action_categories": connection.execute("SELECT * FROM action_categories ORDER BY category_code").fetchall(),
                "unrelated_work_items": connection.execute(
                    "SELECT * FROM work_items WHERE work_item_id <> ? ORDER BY work_item_id",
                    (TARGET_ID,),
                ).fetchall(),
                "original_updates": connection.execute(
                    "SELECT * FROM work_item_updates WHERE work_item_id <> ? OR update_id IN (?, ?) ORDER BY update_id",
                    (TARGET_ID, *sorted(ORIGINAL_UPDATE_IDS)),
                ).fetchall(),
            }
            target = connection.execute(
                "SELECT * FROM work_items WHERE work_item_id = ?",
                (TARGET_ID,),
            ).fetchone()
            total_updates = connection.execute("SELECT COUNT(*) FROM work_item_updates").fetchone()[0]
    except Exception as error:
        return {"score": 0, "detail": f"Could not verify database preservation: {error}"}
    bad = [name for name, rows in checks.items() if _rows_hash(rows) != EXPECTED_DB_HASHES[name]]
    if target is None:
        bad.append("target_work_item_missing")
    else:
        target_dict = dict(target)
        if any(target_dict.get(key) != value for key, value in EXPECTED_TARGET_METADATA.items()):
            bad.append("target_metadata")
    if total_updates != 276:
        bad.append(f"update_count={total_updates}")
    if bad:
        return {"score": 0, "detail": "Unexpected changes detected: " + ", ".join(bad)}
    return {"score": 1, "detail": "All pre-existing Planner records and non-status target metadata are preserved"}


def check_workspace_files_untouched(ws):
    workspace = Path(ws)
    response_file = "answer" + ".md"
    bad = []
    for relative_path, expected_hash in EXPECTED_WORKSPACE_HASHES.items():
        path = workspace / relative_path
        if not path.exists():
            bad.append(f"missing:{relative_path}")
        elif hashlib.sha256(path.read_bytes()).hexdigest() != expected_hash:
            bad.append(f"changed:{relative_path}")
    unexpected = []
    expected_paths = set(EXPECTED_WORKSPACE_HASHES)
    for path in workspace.rglob("*"):
        if path.is_file():
            relative_path = path.relative_to(workspace).as_posix()
            if relative_path != response_file and relative_path not in expected_paths:
                unexpected.append(relative_path)
    if bad or unexpected:
        details = bad + [f"unexpected:{path}" for path in unexpected]
        return {"score": 0, "detail": "Workspace was altered: " + ", ".join(details[:10])}
    return {"score": 1, "detail": "All original workspace files are unchanged"}

def check_operation_summary(ws):
    path = Path(ws) / "answer.md"
    try:
        text = path.read_text(encoding="utf-8")
    except Exception as error:
        return {"score": 0, "detail": f"Could not read final response: {error}"}
    norm = " ".join(text.lower().replace("→", "->").replace("➜", "->").replace(chr(96), "").split())
    required = [TARGET_ID.lower(), "awaitingmanagerdecision", "completed", "cleared", "note"]
    missing = [term for term in required if term not in norm]
    transition_ok = "4 -> 5" in norm or "version 4 to 5" in norm
    completion_clear_ok = ("completed_at" in norm or "completion timestamp" in norm) and ("null" in norm or "cleared" in norm)
    note_ok = (
        ("audit" in norm or "reconciliation" in norm)
        and "note" in norm
        and any(term in norm for term in ("appended", "added", "new "))
    )
    completed_ok = any(term in norm for term in (
        "reconciled", "reconciliation complete", "corrected", "card changed",
        "completed correction", "successfully"
    )) and not any(term in norm for term in ("recommend", "should be", "would be"))
    if missing or not (transition_ok and completion_clear_ok and note_ok and completed_ok):
        detail = "missing required completion summary"
        if missing:
            detail += ": " + ", ".join(missing)
        return {"score": 0, "detail": detail}
    return {"score": 1, "detail": "Final response records the completed reconciliation, version transition, cleared completion time, and one audit note"}
